//! Application binary: Slint UI on KMS/DRM with libmpv render (OpenGL ES).

use std::time::Duration;

/// Code generated by Slint from `ui/placeholder.slint`; it calls `unwrap()` (Chat Master D-58).
#[allow(clippy::unwrap_used)]
mod ui {
    slint::include_modules!();
}

use slint::ComponentHandle;
use ui::Placeholder;

const VERSION: &str = env!("CARGO_PKG_VERSION");
const GIT_HASH: &str = env!("EGSOB_GIT_HASH");
const BUILD_TIME: &str = env!("EGSOB_BUILD_TIME");

fn main() -> Result<(), slint::PlatformError> {
    if std::env::var("EGSOB_UI").as_deref() == Ok("1") {
        run_ui()
    } else {
        println!("egsob {}", build_line());
        Ok(())
    }
}

/// Version, git short hash and build time (Chat Master D-118).
fn build_line() -> String {
    format!("{VERSION} ({GIT_HASH}, {BUILD_TIME})")
}

/// Local wall-clock time as `HH:MM` (24-hour, system time zone).
fn clock_text() -> String {
    chrono::Local::now().format("%H:%M").to_string()
}

/// Shows the placeholder screen on KMS and refreshes the clock every second (D-126).
fn run_ui() -> Result<(), slint::PlatformError> {
    let window = Placeholder::new()?;
    window.set_build_line(build_line().into());
    window.set_clock(clock_text().into());
    let weak = window.as_weak();
    let timer = slint::Timer::default();
    timer.start(
        slint::TimerMode::Repeated,
        Duration::from_secs(1),
        move || {
            if let Some(window) = weak.upgrade() {
                window.set_clock(clock_text().into());
            }
        },
    );
    window.run()
}
